<script setup lang="ts">
import { ref,computed,watch } from 'vue'
import Icon from './Icon.vue'
type Box={box:number[];label:string}
const props=withDefaults(defineProps<{question:any;modelValue:any;guide?:boolean;findOnly?:boolean;labelsVisible?:boolean;disabled?:boolean;standard?:any}>(),{guide:false,findOnly:false,labelsVisible:true,disabled:false})
const emit=defineEmits(['update:modelValue','spot'])
const surface=ref<HTMLElement>(),selected=ref(-1),label=ref(''),drawing=ref(false),draft=ref<number[]|null>(null),poly=ref<number[][]>([]),closed=ref(false),zoom=ref(1),imageError=ref(false)
let start=[0,0],action='draw',original:number[]=[];let history:any[]=[]
const boxes=computed<Box[]>(()=>props.modelValue?.boxes || []);const isPolygon=computed(()=>props.question.type==='polygon')
watch(()=>props.question.id,()=>{selected.value=-1;label.value='';draft.value=null;poly.value=[];closed.value=false;zoom.value=1;imageError.value=false;history=[]})
watch(()=>props.modelValue,v=>{if(isPolygon.value && v?.points){poly.value=v.points;label.value=v.label||'';if(props.disabled)closed.value=poly.value.length>=3}},{immediate:true})
function coord(event:PointerEvent){const r=surface.value!.getBoundingClientRect();return [Math.max(0,Math.min(1,(event.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(event.clientY-r.top)/r.height))]}
function save(value:any){history.push(JSON.parse(JSON.stringify(props.modelValue || {})));emit('update:modelValue',value)}
function down(event:PointerEvent,index=-1,handle=false){
 if(props.disabled)return
 const point=coord(event)
 if(props.findOnly){emit('spot',point);return}
 if(isPolygon.value){if(closed.value)return;poly.value=[...poly.value,point];emit('update:modelValue',{points:poly.value,label:label.value});return}
 start=point;drawing.value=true;action=index>=0?(handle?'resize':'move'):'draw';selected.value=index
 if(index>=0)original=[...boxes.value[index].box];else draft.value=[...point,0,0]
 ;(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId)
}
function move(event:PointerEvent){
 if(!drawing.value||props.disabled)return
 const point=coord(event),dx=point[0]-start[0],dy=point[1]-start[1]
 if(action==='draw'){draft.value=[Math.min(point[0],start[0]),Math.min(point[1],start[1]),Math.abs(dx),Math.abs(dy)]}
 else{const next=boxes.value.map(b=>({box:[...b.box],label:b.label}));if(action==='move')next[selected.value].box=[Math.max(0,Math.min(1-original[2],original[0]+dx)),Math.max(0,Math.min(1-original[3],original[1]+dy)),original[2],original[3]];else next[selected.value].box=[original[0],original[1],Math.max(.005,Math.min(1-original[0],original[2]+dx)),Math.max(.005,Math.min(1-original[1],original[3]+dy))];emit('update:modelValue',{boxes:next})}
}
function up(){if(!drawing.value)return;drawing.value=false;if(action==='draw'&&draft.value&&draft.value[2]>.007&&draft.value[3]>.007){save({boxes:[...boxes.value,{box:draft.value,label:label.value}]});selected.value=boxes.value.length}else if(action==='move'||action==='resize'){const prior=boxes.value.map((b,i)=>i===selected.value?{box:original,label:b.label}:b);history.push({boxes:prior})}draft.value=null}
function chooseLabel(value:string){label.value=value;if(isPolygon.value)emit('update:modelValue',{points:poly.value,label:value});else if(selected.value>=0){const next=boxes.value.map((b,i)=>i===selected.value?{...b,label:value}:b);save({boxes:next})}else if(boxes.value.length===1)save({boxes:boxes.value.map(b=>({...b,label:value}))})}
function remove(){if(isPolygon.value){save({points:[],label:label.value});poly.value=[];closed.value=false}else{save({boxes:boxes.value.filter((_,i)=>i!==selected.value)});selected.value=-1}}
function undo(){if(isPolygon.value){closed.value=false;poly.value=poly.value.slice(0,-1);emit('update:modelValue',{points:poly.value,label:label.value})}else if(history.length)emit('update:modelValue',history.pop())}
function closePolygon(){if(poly.value.length>=3){closed.value=true;emit('update:modelValue',{points:poly.value,label:label.value})}}
function keydown(e:KeyboardEvent){if(props.disabled)return;if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove()}if(e.key==='Escape'){drawing.value=false;draft.value=null}if(e.key==='z'&&(e.ctrlKey||e.metaKey)){e.preventDefault();undo()}if(e.key==='Enter'&&isPolygon.value){e.preventDefault();closePolygon()}if(selected.value>=0 && ['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const b=boxes.value[selected.value],delta=e.shiftKey?.01:.002;const next=boxes.value.map(v=>({...v,box:[...v.box]}));next[selected.value].box[0]=Math.max(0,Math.min(1-b.box[2],b.box[0]+(e.key==='ArrowLeft'?-delta:e.key==='ArrowRight'?delta:0)));next[selected.value].box[1]=Math.max(0,Math.min(1-b.box[3],b.box[1]+(e.key==='ArrowUp'?-delta:e.key==='ArrowDown'?delta:0)));save({boxes:next})}}
const polygonPoints=computed(()=>poly.value.map(p=>`${p[0]*1000},${p[1]*1000}`).join(' '))
</script>
<template><div class="annotation-component"><div class="annotation-toolbar" v-if="!findOnly"><div class="tool-group"><button class="tool-button active" :aria-label="isPolygon?'多边形工具':'矩形工具'"><Icon :name="isPolygon?'Shapes':'SquareDashed'" :size="18"/></button><span>{{isPolygon?'逐点描绘轮廓':'按住并拖动，画出边界框'}}</span></div><div class="tool-group"><button class="tool-button" :disabled="disabled" @click="undo" aria-label="撤销"><Icon name="RotateCcw" :size="17"/></button><button class="tool-button" :disabled="disabled||(!isPolygon&&selected<0)" @click="remove" aria-label="删除选中标注"><Icon name="Trash2" :size="17"/></button><span class="tool-divider"></span><button class="tool-button" @click="zoom=Math.max(1,zoom-.25)" aria-label="缩小"><Icon name="ZoomOut" :size="18"/></button><span class="zoom-label">{{Math.round(zoom*100)}}%</span><button class="tool-button" @click="zoom=Math.min(2,zoom+.25)" aria-label="放大"><Icon name="ZoomIn" :size="18"/></button></div></div><div class="canvas-scroll"><div class="annotation-surface" :class="{finding:findOnly,readonly:disabled}" ref="surface" tabindex="0" role="application" :aria-label="findOnly?'点击图片中任务要求的目标':'图像标注画布；拖动画框，选中后可用方向键微调，删除键删除'" :style="{aspectRatio:question.width+'/'+question.height,width:zoom*100+'%',maxWidth:zoom*490*question.width/question.height+'px',minWidth:'0',margin:'0 auto'}" @keydown="keydown"><img :src="question.image" alt="本题待标注图像" draggable="false" @error="imageError=true"><div v-if="imageError" class="image-error">图片加载失败，请刷新后重试。</div><svg viewBox="0 0 1000 1000" preserveAspectRatio="none" class="annotation-overlay" @pointerdown="down($event)" @pointermove="move" @pointerup="up" @pointercancel="up"><rect v-if="guide&&question.guide_box" class="guide-box" :x="question.guide_box[0]*1000" :y="question.guide_box[1]*1000" :width="question.guide_box[2]*1000" :height="question.guide_box[3]*1000"/><template v-for="(b,i) in boxes" :key="i"><rect class="user-box" :class="{selected:selected===i}" :x="b.box[0]*1000" :y="b.box[1]*1000" :width="b.box[2]*1000" :height="b.box[3]*1000" @pointerdown.stop="down($event,i)" @pointermove="move" @pointerup="up"/><text v-if="b.label" :x="b.box[0]*1000+7" :y="Math.max(25,b.box[1]*1000-9)" class="box-label">{{b.label}}</text><rect v-if="selected===i&&!disabled" class="resize-handle" :x="(b.box[0]+b.box[2])*1000-6" :y="(b.box[1]+b.box[3])*1000-6" width="12" height="12" @pointerdown.stop="down($event,i,true)" @pointermove="move" @pointerup="up"/></template><rect v-if="draft" class="user-box draft" :x="draft[0]*1000" :y="draft[1]*1000" :width="draft[2]*1000" :height="draft[3]*1000"/><polygon v-if="isPolygon&&closed" class="user-polygon" :points="polygonPoints"/><polyline v-else-if="isPolygon" class="user-polyline" :points="polygonPoints"/><circle v-for="(p,i) in poly" :key="i" :cx="p[0]*1000" :cy="p[1]*1000" r="5" class="poly-dot"/><template v-if="standard&&question.type==='box'"><rect v-for="(b,i) in standard" :key="i" class="standard-box" :x="b.box[0]*1000" :y="b.box[1]*1000" :width="b.box[2]*1000" :height="b.box[3]*1000"/></template><polygon v-if="standard&&question.type==='polygon'" class="standard-polygon" :points="standard.polygon.map((p:number[])=>`${p[0]*1000},${p[1]*1000}`).join(' ')"/></svg></div></div><div v-if="isPolygon&&!closed&&!disabled" class="polygon-controls"><span>已放置 {{poly.length}} 个点</span><button class="btn small outline" :disabled="poly.length<3" @click="closePolygon">闭合多边形<Icon name="Check" :size="15"/></button></div><div class="annotation-labels" v-if="labelsVisible&&!findOnly"><label>选择标签</label><div><button v-for="l in question.labels" :key="l" :disabled="disabled" class="label-chip" :class="{selected:label===l||boxes[selected]?.label===l}" @click="chooseLabel(l)"><span></span>{{l}}<Icon v-if="label===l||boxes[selected]?.label===l" name="Check" :size="13"/></button></div><span class="annotation-count">{{isPolygon?poly.length+' 个顶点':boxes.length+' 个标注框'}}</span></div><div v-if="!findOnly" class="canvas-caption"><span>{{guide?'虚线框是操作引导，试着画出自己的框。':isPolygon?'按顺序点击边界，完成后闭合多边形。':'选中标注框可移动；拖动右下角可缩放，方向键可微调。'}}</span><a :href="question.source_url" target="_blank" rel="noopener noreferrer">素材来源<Icon name="ArrowUpRight" :size="12"/></a></div></div></template>
